import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DB_FILE = path.join(__dirname, '../../data/db.json');

// Đọc dữ liệu từ file db.json
export function readDb() {
  try {
    const raw = fs.readFileSync(DB_FILE, 'utf-8');
    return JSON.parse(raw);
  } catch (error) {
    console.error('Lỗi khi đọc file db.json:', error);
    return { projects: [], employees: [], tasks: [], overtimes: [], ganttItems: [] };
  }
}

// Lưu dữ liệu vào file db.json
export function writeDb(data) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2), 'utf-8');
    return true;
  } catch (error) {
    console.error('Lỗi khi ghi file db.json:', error);
    return false;
  }
}

import { readDb, writeDb } from '../models/db.js';

/**
 * Controller Quản Lý Nhân Sự (HR)
 * Quản lý danh sách nhân sự, trạng thái có mặt tại công trường (On-site),
 * và số lượng task được giao cho từng người.
 */

// Lấy danh sách toàn bộ nhân sự kèm số task đang phụ trách
export function getEmployees(req, res) {
  const db = readDb();
  const tasks = db.tasks || [];
  const overtimes = db.overtimes || [];

  // Tính số lượng task và giờ OT cho từng nhân viên
  const employeesWithStats = db.employees.map(emp => {
    const assignedTasks = tasks.filter(t => t.employeeId === emp.id);
    const empOvertimes = overtimes.filter(o => o.employeeId === emp.id);
    const totalOtHours = empOvertimes.reduce((sum, o) => sum + (Number(o.hours) || 0), 0);

    return {
      ...emp,
      taskCount: assignedTasks.length,
      tasks: assignedTasks.map(t => ({ id: t.id, title: t.title, status: t.status })),
      totalOtHours: Math.round(totalOtHours * 10) / 10
    };
  });

  return res.json({
    success: true,
    data: employeesWithStats,
    meta: {
      total: employeesWithStats.length,
      onSiteCount: employeesWithStats.filter(e => e.isOnSite).length,
      standardHoursPerPerson: 8
    }
  });
}

// Thêm nhân sự mới
export function createEmployee(req, res) {
  const db = readDb();
  const { name, title, team, phone, email, standardHours } = req.body;

  if (!name || !title) {
    return res.status(400).json({ success: false, message: 'Vui lòng nhập họ tên và chức danh' });
  }

  const newEmployee = {
    id: `emp-${Date.now()}`,
    code: `NV-${String(db.employees.length + 1).padStart(3, '0')}`,
    name,
    title,
    team: team || 'Ban Quản Lý',
    phone: phone || 'Đang cập nhật',
    email: email || '',
    standardHours: Number(standardHours) || 8,
    isOnSite: true,
    checkInTime: new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' }),
    avatar: `https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=120&auto=format&fit=crop&q=80`
  };

  db.employees.push(newEmployee);
  writeDb(db);

  return res.status(201).json({
    success: true,
    message: 'Tạo nhân sự mới thành công',
    data: newEmployee
  });
}

// Chuyển đổi trạng thái có mặt tại công trường (Vào / Ra ca)
export function toggleOnSite(req, res) {
  const db = readDb();
  const { id } = req.params;

  const emp = db.employees.find(e => e.id === id);
  if (!emp) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy nhân sự' });
  }

  emp.isOnSite = !emp.isOnSite;
  if (emp.isOnSite) {
    emp.checkInTime = new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' });
  } else {
    emp.checkInTime = null;
  }

  writeDb(db);

  return res.json({
    success: true,
    message: `Đã cập nhật trạng thái của ${emp.name}: ${emp.isOnSite ? 'Có mặt tại công trường' : 'Đã rời công trường'}`,
    data: emp
  });
}

// Xóa nhân sự
export function deleteEmployee(req, res) {
  const db = readDb();
  const { id } = req.params;

  const index = db.employees.findIndex(e => e.id === id);
  if (index === -1) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy nhân sự' });
  }

  const removed = db.employees.splice(index, 1);
  writeDb(db);

  return res.json({
    success: true,
    message: `Đã xóa nhân sự ${removed[0].name}`,
    data: removed[0]
  });
}

import { readDb, writeDb } from '../models/db.js';

/**
 * Controller Quản Lý Phân Công & Tăng Ca
 * Xử lý giao việc cho nhân sự, kiểm soát giờ làm việc chuẩn (8h/ngày),
 * và đăng ký ca làm thêm giờ (Overtime / OT) cho các công việc gấp.
 */

// Lấy danh sách nhiệm vụ và tăng ca
export function getTasks(req, res) {
  const db = readDb();
  return res.json({
    success: true,
    data: {
      tasks: db.tasks || [],
      overtimes: db.overtimes || []
    }
  });
}

// Tạo nhiệm vụ mới (Task Assignment)
export function createTask(req, res) {
  const db = readDb();
  const {
    projectId,
    projectName,
    phase,
    title,
    employeeId,
    startDate,
    endDate,
    estimatedDays,
    priority,
    notes
  } = req.body;

  if (!title || !employeeId) {
    return res.status(400).json({ success: false, message: 'Vui lòng nhập tên công việc và chọn người đảm nhận' });
  }

  // Tìm tên nhân sự
  const emp = db.employees.find(e => e.id === employeeId);
  const employeeName = emp ? emp.name : 'Chưa phân công';

  // Tìm tên dự án nếu có
  let projName = projectName;
  if (!projName && projectId) {
    const proj = db.projects.find(p => p.id === projectId);
    if (proj) projName = proj.name;
  }

  const days = Number(estimatedDays) || 1;
  const hours = days * 8; // 8 tiếng / ngày chuẩn

  const newTask = {
    id: `task-${Date.now()}`,
    projectId: projectId || 'proj-1',
    projectName: projName || 'DỰ ÁN XÂY DỰNG TRUNG TÂM CÔNG NGHỆ APS VIỆT NAM',
    phase: phase || 'A. THIẾT KẾ XÂY DỰNG',
    title,
    employeeId,
    employeeName,
    startDate: startDate || new Date().toISOString().split('T')[0],
    endDate: endDate || new Date().toISOString().split('T')[0],
    estimatedHours: hours,
    estimatedDays: days,
    status: 'in_progress',
    speedStatus: 'on_time', // 'early', 'on_time', 'delayed'
    priority: priority || 'normal', // 'normal', 'high', 'urgent'
    progress: 0,
    notes: notes || ''
  };

  db.tasks.push(newTask);

  // Đồng thời thêm vào Gantt Chart nếu cần
  const newGanttItem = {
    id: `G-${Date.now()}`,
    code: `T${db.tasks.length}`,
    title,
    isGroup: false,
    color: '#0284c7',
    unit: 'APS',
    startDate: newTask.startDate,
    endDate: newTask.endDate,
    days: newTask.estimatedDays,
    assignee: employeeName,
    notes: notes || '',
    status: 'in_progress',
    speed: 'on_time',
    progress: 0,
    dependencies: []
  };
  db.ganttItems.push(newGanttItem);

  writeDb(db);

  return res.status(201).json({
    success: true,
    message: 'Phân công nhiệm vụ thành công',
    data: newTask
  });
}

// Cập nhật trạng thái nhiệm vụ (Hoàn thành, Đang làm, Nhanh/Chậm)
export function updateTask(req, res) {
  const db = readDb();
  const { id } = req.params;
  const { status, progress, speedStatus, notes } = req.body;

  const task = db.tasks.find(t => t.id === id);
  if (!task) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy nhiệm vụ' });
  }

  if (status !== undefined) task.status = status;
  if (progress !== undefined) task.progress = Number(progress);
  if (speedStatus !== undefined) task.speedStatus = speedStatus;
  if (notes !== undefined) task.notes = notes;

  if (task.progress === 100) {
    task.status = 'completed';
  }

  writeDb(db);

  return res.json({
    success: true,
    message: 'Cập nhật nhiệm vụ thành công',
    data: task
  });
}

// Xóa nhiệm vụ
export function deleteTask(req, res) {
  const db = readDb();
  const { id } = req.params;

  const index = db.tasks.findIndex(t => t.id === id);
  if (index === -1) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy nhiệm vụ' });
  }

  const removed = db.tasks.splice(index, 1);
  writeDb(db);

  return res.json({
    success: true,
    message: 'Đã xóa nhiệm vụ thành công',
    data: removed[0]
  });
}

// Đăng ký ca làm việc tăng ca (Overtime / OT)
export function createOvertime(req, res) {
  const db = readDb();
  const { taskId, employeeId, hours, date, reason } = req.body;

  if (!employeeId || !hours) {
    return res.status(400).json({ success: false, message: 'Vui lòng chọn nhân viên và số giờ tăng ca' });
  }

  const emp = db.employees.find(e => e.id === employeeId);
  const task = taskId ? db.tasks.find(t => t.id === taskId) : null;

  const newOt = {
    id: `ot-${Date.now()}`,
    taskId: taskId || 'general',
    taskTitle: task ? task.title : 'Tăng ca đột xuất tại công trường',
    employeeId,
    employeeName: emp ? emp.name : 'Chưa xác định',
    hours: Number(hours),
    date: date || new Date().toISOString().split('T')[0],
    reason: reason || 'Hoàn thành công việc khẩn cấp',
    approvedBy: 'Trần Quốc Hưng (Chỉ huy trưởng)',
    status: 'approved'
  };

  db.overtimes.push(newOt);

  // Nếu gắn với Gantt item tương ứng, cập nhật overtimeHours
  if (taskId) {
    const gantt = db.ganttItems.find(g => g.title === (task ? task.title : ''));
    if (gantt) {
      gantt.overtimeHours = (gantt.overtimeHours || 0) + Number(hours);
    }
  }

  writeDb(db);

  return res.status(201).json({
    success: true,
    message: `Đã đăng ký ${hours}h tăng ca cho ${newOt.employeeName}`,
    data: newOt
  });
}

import { readDb, writeDb } from '../models/db.js';

/**
 * Controller Quản Lý Tiến Độ Dự Án & Biểu Đồ Gantt Công Trường
 * Xử lý dữ liệu WBS (Phân rã công việc), mốc thời gian, liên kết phụ thuộc FS,
 * và hiển thị biểu đồ Gantt tiến độ công trình APS.
 */

// Lấy danh sách dự án
export function getProjects(req, res) {
  const db = readDb();
  return res.json({
    success: true,
    data: db.projects || []
  });
}

// Tạo dự án mới
export function createProject(req, res) {
  const db = readDb();
  const { name, code, description, location, manager, startDate, endDate } = req.body;

  if (!name) {
    return res.status(400).json({ success: false, message: 'Vui lòng nhập tên dự án' });
  }

  const newProject = {
    id: `proj-${Date.now()}`,
    code: code || `APS-${new Date().getFullYear()}-${db.projects.length + 1}`,
    name,
    description: description || '',
    location: location || 'Hà Nội',
    manager: manager || 'Trần Quốc Hưng',
    startDate: startDate || new Date().toISOString().split('T')[0],
    endDate: endDate || '2027-12-31',
    status: 'planning',
    progress: 0
  };

  db.projects.push(newProject);
  writeDb(db);

  return res.status(201).json({
    success: true,
    message: 'Tạo dự án mới thành công',
    data: newProject
  });
}

// Lấy danh sách hạng mục cho biểu đồ Gantt
export function getGanttItems(req, res) {
  const db = readDb();
  return res.json({
    success: true,
    data: db.ganttItems || []
  });
}

// Thêm mới công việc vào biểu đồ Gantt dự án
export function createGanttItem(req, res) {
  const db = readDb();
  const {
    code,
    title,
    isGroup,
    unit,
    startDate,
    endDate,
    days,
    assignee,
    notes,
    color,
    dependencies,
    speed
  } = req.body;

  if (!title || !startDate || !endDate) {
    return res.status(400).json({ success: false, message: 'Vui lòng nhập đầy đủ tên công việc, ngày bắt đầu và ngày kết thúc' });
  }

  const start = new Date(startDate);
  const end = new Date(endDate);
  const calculatedDays = days ? Number(days) : Math.max(1, Math.round((end - start) / (1000 * 60 * 60 * 24)) + 1);

  const newItem = {
    id: `G-${Date.now()}`,
    code: code || `T${db.ganttItems.length + 1}`,
    title,
    isGroup: Boolean(isGroup),
    color: color || '#0284c7',
    unit: unit || 'APS',
    startDate,
    endDate,
    days: calculatedDays,
    assignee: assignee || 'Đang phân công',
    notes: notes || '',
    status: 'in_progress',
    speed: speed || 'on_time',
    progress: 0,
    dependencies: dependencies || []
  };

  db.ganttItems.push(newItem);
  writeDb(db);

  return res.status(201).json({
    success: true,
    message: 'Thêm công việc vào tiến độ dự án thành công',
    data: newItem
  });
}

// Xóa công việc khỏi biểu đồ Gantt
export function deleteGanttItem(req, res) {
  const db = readDb();
  const { id } = req.params;

  const index = db.ganttItems.findIndex(g => g.id === id);
  if (index === -1) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy công việc' });
  }

  const removed = db.ganttItems.splice(index, 1);
  writeDb(db);

  return res.json({
    success: true,
    message: `Đã xóa công việc "${removed[0].title}" khỏi tiến độ`,
    data: removed[0]
  });
}

import { readDb } from '../models/db.js';

/**
 * Controller Thống Kê & Báo Cáo Hiệu Suất (Dashboard & Analytics)
 * Tổng hợp toàn diện tiến độ các công việc trong dự án, nhân viên đảm nhận,
 * thời gian hoàn thành, tình trạng nhanh/chậm và giờ tăng ca.
 */

export function getStats(req, res) {
  const db = readDb();
  const employees = db.employees || [];
  const tasks = db.tasks || [];
  const overtimes = db.overtimes || [];
  const projects = db.projects || [];
  const ganttItems = db.ganttItems || [];

  // Thống kê nhân sự on-site
  const totalEmployees = employees.length;
  const onSiteEmployees = employees.filter(e => e.isOnSite).length;

  // Thống kê tasks
  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(t => t.status === 'completed').length;
  const inProgressTasks = tasks.filter(t => t.status === 'in_progress').length;
  const delayedTasks = tasks.filter(t => t.speedStatus === 'delayed').length;
  const earlyTasks = tasks.filter(t => t.speedStatus === 'early').length;
  const onTimeTasks = tasks.filter(t => t.speedStatus === 'on_time').length;

  // Tổng số giờ OT
  const totalOtHours = overtimes.reduce((sum, o) => sum + (Number(o.hours) || 0), 0);

  // Thống kê hiệu suất theo từng nhân viên
  const employeePerformance = employees.map(emp => {
    const empTasks = tasks.filter(t => t.employeeId === emp.id);
    const completed = empTasks.filter(t => t.status === 'completed').length;
    const empOt = overtimes
      .filter(o => o.employeeId === emp.id)
      .reduce((sum, o) => sum + (Number(o.hours) || 0), 0);

    const completionRate = empTasks.length > 0 ? Math.round((completed / empTasks.length) * 100) : 0;

    return {
      id: emp.id,
      name: emp.name,
      title: emp.title,
      team: emp.team,
      avatar: emp.avatar,
      isOnSite: emp.isOnSite,
      totalAssignedTasks: empTasks.length,
      completedTasks: completed,
      completionRate,
      otHours: Math.round(empOt * 10) / 10
    };
  });

  // Tiến độ từng dự án
  const projectSummaries = projects.map(proj => {
    const projTasks = tasks.filter(t => t.projectId === proj.id);
    const completed = projTasks.filter(t => t.status === 'completed').length;
    const rate = projTasks.length > 0 ? Math.round((completed / projTasks.length) * 100) : proj.progress;

    return {
      id: proj.id,
      name: proj.name,
      code: proj.code,
      manager: proj.manager,
      startDate: proj.startDate,
      endDate: proj.endDate,
      totalTasks: projTasks.length,
      completedTasks: completed,
      progressRate: rate
    };
  });

  return res.json({
    success: true,
    data: {
      overview: {
        totalProjects: projects.length,
        totalEmployees,
        onSiteEmployees,
        totalTasks,
        completedTasks,
        inProgressTasks,
        delayedTasks,
        earlyTasks,
        onTimeTasks,
        totalOtHours: Math.round(totalOtHours * 10) / 10,
        overallCompletionRate: totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 45
      },
      employeePerformance,
      projectSummaries
    }
  });
}

